// Dot VPN Compose theme. Generated by design/scripts/generate.py; edit there.
package dot.vpn.payam.ui.theme

import androidx.compose.foundation.isSystemInDarkTheme
import androidx.compose.material3.MaterialTheme
import androidx.compose.material3.darkColorScheme
import androidx.compose.material3.lightColorScheme
import androidx.compose.runtime.Composable
import androidx.compose.runtime.CompositionLocalProvider

/**
 * Wrap the app in this. Material slots are mapped so stock components follow
 * the Signal kit: primary is ink (buttons are black or white, never lime).
 * Read brand-only colours with DotTheme.colors.signal etc.
 */
@Composable
fun DotVpnTheme(
    darkTheme: Boolean = isSystemInDarkTheme(),
    persian: Boolean = false,
    content: @Composable () -> Unit,
) {
    val c = if (darkTheme) DarkDotColors else LightDotColors
    val scheme = if (darkTheme) darkColorScheme(
        primary = c.fg, onPrimary = c.bg,
        secondary = c.fgMuted, onSecondary = c.bg,
        background = c.bg, onBackground = c.fg,
        surface = c.bg, onSurface = c.fg,
        surfaceVariant = c.surface2, onSurfaceVariant = c.fgMuted,
        outline = c.border, outlineVariant = c.border,
        error = c.danger, onError = c.bg,
    ) else lightColorScheme(
        primary = c.fg, onPrimary = c.bg,
        secondary = c.fgMuted, onSecondary = c.bg,
        background = c.bg, onBackground = c.fg,
        surface = c.bg, onSurface = c.fg,
        surfaceVariant = c.surface2, onSurfaceVariant = c.fgMuted,
        outline = c.border, outlineVariant = c.border,
        error = c.danger, onError = c.bg,
    )
    CompositionLocalProvider(LocalDotColors provides c) {
        MaterialTheme(colorScheme = scheme, typography = dotTypography(persian), content = content)
    }
}

object DotTheme {
    val colors: DotColors
        @Composable get() = LocalDotColors.current
}
